begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
-- Rollback-only SQL proof; real deletes are also exercised through Storage HTTP.
set local storage.allow_delete_query='true';
select has_table('private','event_images','durable event image attachments exist');
select is((select public from storage.buckets where id='event-images'),false,'bucket is private');
insert into auth.users(id,email) values ('15150000-0000-4000-8000-000000000001','image-owner@example.invalid'),('15150000-0000-4000-8000-000000000002','image-foreign@example.invalid');
insert into public.organizers(id,display_name) values ('15150000-0000-4000-8000-000000000001','Image owner'),('15150000-0000-4000-8000-000000000002','Foreign owner');
insert into public.events(id,organizer_id) values ('15150000-0000-4000-8000-000000000010','15150000-0000-4000-8000-000000000001');
select set_config('request.jwt.claim.sub','15150000-0000-4000-8000-000000000001',true);
insert into storage.objects(id,bucket_id,name,metadata) select ('15150000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'event-images','15150000-0000-4000-8000-000000000010/'||('15150000-0000-4000-8000-'||lpad(n::text,12,'0'))||'.png','{"size":100,"mimetype":"image/png"}' from generate_series(101,103) n;
select is(jsonb_array_length(public.list_event_images(array['15150000-0000-4000-8000-000000000010'::uuid])),3,'owner sees three persisted images');
select throws_ok($$insert into storage.objects(bucket_id,name,metadata) values('event-images','15150000-0000-4000-8000-000000000010/15150000-0000-4000-8000-000000000104.png','{"size":100,"mimetype":"image/png"}')$$,'P0001','EVENT_IMAGE_LIMIT','fourth upload rejected server-side');
select throws_ok($$insert into storage.objects(bucket_id,name,metadata) values('event-images','15150000-0000-4000-8000-000000000010/15150000-0000-4000-8000-000000000104.png','{"size":100,"mimetype":"image/svg+xml"}')$$,'P0001','INVALID_IMAGE_FILE','unsupported MIME rejected server-side');
select throws_ok($$insert into storage.objects(bucket_id,name,metadata) values('event-images','15150000-0000-4000-8000-000000000010/15150000-0000-4000-8000-000000000104.png','{"size":5242881,"mimetype":"image/png"}')$$,'P0001','INVALID_IMAGE_FILE','oversized image rejected server-side');
set local role authenticated;
select public.reorder_event_images('15150000-0000-4000-8000-000000000010',array['15150000-0000-4000-8000-000000000103','15150000-0000-4000-8000-000000000102','15150000-0000-4000-8000-000000000101']::uuid[]);
select is(public.list_event_images(array['15150000-0000-4000-8000-000000000010'::uuid])->0->>'id','15150000-0000-4000-8000-000000000103','reorder persists primary image');
select throws_ok($$select public.reorder_event_images('15150000-0000-4000-8000-000000000010',array['15150000-0000-4000-8000-000000000103']::uuid[])$$,'P0001','IMAGE_ORDER_CONFLICT','stale or incomplete ordering rejected');
select set_config('request.jwt.claim.sub','15150000-0000-4000-8000-000000000002',true);
select is(public.list_event_images(array['15150000-0000-4000-8000-000000000010'::uuid]),'[]'::jsonb,'foreign owner cannot read draft images');
select is((select count(*) from storage.objects where bucket_id='event-images'),0::bigint,'foreign storage reads denied');
select throws_ok($$insert into storage.objects(bucket_id,name,metadata) values('event-images','15150000-0000-4000-8000-000000000010/15150000-0000-4000-8000-000000000104.png','{"size":100,"mimetype":"image/png"}')$$,'42501',null,'foreign upload denied');
select throws_ok($$select public.reorder_event_images('15150000-0000-4000-8000-000000000010',array['15150000-0000-4000-8000-000000000103']::uuid[])$$,'P0001','IMAGE_EVENT_NOT_OWNED','foreign reorder denied');
delete from storage.objects where bucket_id='event-images';
reset role;
select is((select count(*) from private.event_images where event_id='15150000-0000-4000-8000-000000000010'),3::bigint,'foreign removal changes nothing');
select set_config('request.jwt.claim.sub','',true);
set local role anon;
select is(public.list_event_images(array['15150000-0000-4000-8000-000000000010'::uuid]),'[]'::jsonb,'anonymous cannot read draft images');
reset role;
select set_config('request.jwt.claim.sub','15150000-0000-4000-8000-000000000001',true);
set local role authenticated;
delete from storage.objects where id='15150000-0000-4000-8000-000000000103';
select is(jsonb_array_length(public.list_event_images(array['15150000-0000-4000-8000-000000000010'::uuid])),2,'deleting storage removes durable attachment');
reset role;
select ok(not has_function_privilege('anon','public.server_get_public_event_image(uuid)','execute'),'public cannot call privileged delivery lookup');
select ok(not has_function_privilege('authenticated','public.server_can_manage_event_images(uuid,uuid)','execute'),'owner cannot call service ownership probe');
select ok(has_function_privilege('service_role','public.server_get_public_event_image(uuid)','execute'),'delivery worker has narrow lookup');
select * from finish();
rollback;
